    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Momentlisten gengiver i store træk vejledningen korrekt. Svaret fremstiller den dog som en afsluttende opremsning ('følgende aspekter') uden at sige, at der er tale om eksempler ('f.eks.') i en samlet individuel vurdering. Rubrikkens material_errors dækker netop en liste, der fremstilles som udtømmende. Svaret udelader desuden 'hvad den uddannelsessøgende fejler' og kravet om, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret. Samlet er der væsentlige mangler."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret mangler to kritiske elementer. Det første er den individuelle samlede vurdering af aktuelle symptomer på et velbeskrevet, lægefagligt dokumenteret grundlag. Svaret nævner kun, at aspekterne vurderes på baggrund af uploadede lægefaglige oplysninger. Det andet er 'hvad funktionsnedsættelsen består i' (hvad den uddannelsessøgende fejler). Punkt 1 nævner kun påvirkningen af daglig funktion. Behandling og sygdomshistorik er dækket."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvad Udbetaling Danmark lægger vægt på ved vurderingen af sværhedsgraden."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen kilde, hverken en bestemmelse eller en vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Alle momenter og udsagnet om uploadede lægefaglige oplysninger findes i vejledningspassagen. Svaret tilføjer ingen ny regel, betingelse eller myndighed."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Den krævede kvalifikation er, at momenterne er eksempler i en konkret individuel helhedsvurdering og ikke selvstændige betingelser. Svaret mangler 'f.eks.'/'blandt andet' og nævner hverken helhedsvurderingen eller individuel vurdering. Dermed bevares forbeholdet ikke."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er en enkel opremsning uden indbyrdes modstridende trin. Der er ingen konklusion, som ikke følger af det, der siges."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret indleder med 'lægger vægt på følgende aspekter' og gør dermed en eksemplificerende liste (f.eks.) til en tilsyneladende fast og udtømmende liste. Det mister kildens ikke-absolutte formulering. Rimelig medvirken er derimod gengivet korrekt som 'i rimeligt omfang'."
    }
  },
  "xhaile_coverage": {
    "A14": {
      "label": "partial",
      "reason": "Svaret gengiver de fire momentgrupper bortset fra 'hvad den uddannelsessøgende fejler'. Det nævner, at vurderingen bygger på uploadede lægefaglige oplysninger. Det nævner ikke kravet om, at funktionsnedsættelsen skal være velbeskrevet og lægefagligt dokumenteret. Det nævner heller ikke, at listen er eksemplificerende, eller at det er styrelsen, der foretager en samlet vurdering."
    }
  },
  "overall_notes": "Indholdet af momentlisten er stort set korrekt og i overensstemmelse med vejledningens afsnit 3.4.1.2. Svaret udelader dog den samlede individuelle helhedsvurdering, momentet 'hvad den uddannelsessøgende fejler' og det eksemplificerende præg ('f.eks.'). Desuden angiver svaret ingen kilde, så C04 er not_met og C05 og C06 er not_assessable."
}

